// Radar do YouTube (multi-nicho) - nó "Montar buscas": escolhe os nichos que cabem na cota do dia e monta uma busca por (nicho, palavra-chave).
// Entradas: "Ler config", "Ler nichos", "Ler ranking" (para saber quais nichos já foram feitos neste ciclo) e, como entrada deste nó, a aba execucoes (chamadas de hoje).
// Ciclo = o domingo da semana (no teste manual, "teste"). Um nicho nunca é dividido: se as palavras dele não cabem na cota de hoje, ele fica para o dia seguinte.
const cfg = {};
$('Ler config').all().forEach(function (it) {
  const r = it.json || {};
  if (r.chave !== undefined && String(r.chave).trim() !== '') cfg[String(r.chave).trim()] = r.valor;
});
const num = function (v, padrao) {
  if (v === undefined || v === null || String(v).trim() === '') return padrao;
  const n = Number(String(v).replace(',', '.'));
  return isFinite(n) ? n : padrao;
};
let modo = 'semanal';
try {
  if ($('Teste manual').isExecuted) modo = 'teste';
} catch (e) {
  modo = 'semanal';
}
const agora = new Date();
const agoraBr = agora.toLocaleString('sv-SE', { timeZone: 'America/Sao_Paulo' }).slice(0, 16); // AAAA-MM-DD HH:MM (Brasília)
const hoje = agoraBr.slice(0, 10);
const diaSemana = new Date(hoje + 'T12:00:00Z').getUTCDay(); // 0 = domingo
const domingo = new Date(Date.parse(hoje + 'T12:00:00Z') - diaSemana * 86400000).toISOString().slice(0, 10);
const ciclo = modo === 'teste' ? 'teste' : domingo;
const limite = num(cfg.limite_search_dia, 90);
let usadas = 0;
$input.all().forEach(function (it) {
  const r = it.json || {};
  if (String(r.data_execucao || '').slice(0, 10) === hoje) usadas += num(r.chamadas_search_list, 0);
});
const sim = function (v) { return ['sim', 's', 'true', '1', 'x', 'yes'].indexOf(String(v === undefined ? '' : v).trim().toLowerCase()) >= 0; };
const avisos = [];
let ativos = [];
$('Ler nichos').all().forEach(function (it) {
  const r = it.json || {};
  const nome = String(r.nicho || '').trim();
  if (!nome || !sim(r.ativo)) return;
  let kws = String(r.palavras_chave || '').split(/[;,]/).map(function (s) { return s.trim(); }).filter(Boolean);
  if (kws.length < 1) { avisos.push('nicho "' + nome + '" sem palavras-chave; ignorado'); return; }
  if (kws.length > 5) { avisos.push('nicho "' + nome + '" tem ' + kws.length + ' palavras; só as 5 primeiras valem'); kws = kws.slice(0, 5); }
  ativos.push({ nicho: nome, kws: kws, regionCode: String(r.regionCode || 'BR').trim().toUpperCase(), relevanceLanguage: String(r.relevanceLanguage || 'pt').trim().toLowerCase() });
});
const feitos = {};
$('Ler ranking').all().forEach(function (it) {
  const r = it.json || {};
  if (String(r.ciclo || '') === ciclo && r.nicho) feitos[String(r.nicho)] = true;
});
let pendentes;
if (modo === 'teste') {
  const nn = Math.max(1, Math.round(num(cfg.teste_num_nichos, 3)));
  const pp = Math.max(1, Math.round(num(cfg.teste_palavras_por_nicho, 2)));
  pendentes = ativos.slice(0, nn).map(function (n) { return Object.assign({}, n, { kws: n.kws.slice(0, pp) }); });
} else {
  pendentes = ativos.filter(function (n) { return !feitos[n.nicho]; });
}
const orcamento = Math.max(0, limite - usadas);
const escolhidos = [];
let gasto = 0;
pendentes.forEach(function (n, i) {
  if (escolhidos.length !== i) return; // já parou: o resto fica para amanhã
  let kws = n.kws;
  if (!escolhidos.length && kws.length > limite) kws = kws.slice(0, Math.max(1, limite));
  if (gasto + kws.length <= orcamento) {
    escolhidos.push(Object.assign({}, n, { kws: kws }));
    gasto += kws.length;
  }
});
const c = {
  duracao_max_s: num(cfg.duracao_max_s, 90),
  inscritos_max: num(cfg.inscritos_max, 50000),
  views_min: num(cfg.views_min, 5000),
  janela_dias: num(cfg.janela_dias, 14),
  resultados_por_busca: Math.max(1, Math.min(50, Math.round(num(cfg.resultados_por_busca, 50)))),
  filtrar_idioma: String(cfg.filtrar_idioma === undefined ? 'sim' : cfg.filtrar_idioma).trim().toLowerCase() !== 'nao',
  email_destino: String(cfg.email_destino || ''),
  top_por_nicho: Math.max(1, Math.round(num(cfg.top_por_nicho_email, 5))),
};
const restantes = pendentes.length - escolhidos.length;
const comum = {
  modo: modo, hoje: hoje, agora_br: agoraBr, ciclo: ciclo, limite_search_dia: limite, chamadas_ja_usadas_hoje: usadas,
  nichos_ativos: ativos.length, nichos_pendentes_no_inicio: pendentes.length, nichos_restantes_para_amanha: restantes,
  completo_apos: restantes === 0, avisos: avisos, cfg: c,
};
if (!escolhidos.length) {
  let motivo = 'nada a fazer';
  if (!ativos.length) motivo = 'nenhum nicho ativo na aba nichos';
  else if (!pendentes.length) motivo = 'ciclo ' + ciclo + ' já completo (todos os nichos ativos já têm ranking); nada a fazer';
  else motivo = 'cota de search.list do dia não comporta o próximo nicho (' + usadas + ' de ' + limite + ' chamadas já usadas hoje); continua amanhã';
  return [{ json: Object.assign({ abortado: true, motivo: motivo }, comum) }];
}
const apos = new Date(agora.getTime() - c.janela_dias * 86400000).toISOString();
const saida = [];
escolhidos.forEach(function (n) {
  n.kws.forEach(function (q) {
    saida.push({ json: Object.assign({ abortado: false, nicho: n.nicho, q: q, regionCode: n.regionCode, relevanceLanguage: n.relevanceLanguage, publishedAfter: apos, maxResults: c.resultados_por_busca }, comum) });
  });
});
return saida;

// Radar do YouTube (multi-nicho) - nó "Consolidar buscas": junta as respostas do search.list POR NICHO, tira duplicados dentro do nicho (guardando todas as palavras que
// acharam o vídeo) e monta lotes de até 50 ids ÚNICOS (de todos os nichos) para o videos.list. Erros 403 (cota, escopo) viram texto em meta.erros; nada aqui lança erro.
const buscas = $('Montar buscas').all();
const respostas = $input.all();
const porNicho = {};
const erros = [];
let chamadas = 0;
let quotaExcedida = false;
let erroEscopo = false;
respostas.forEach(function (it, i) {
  chamadas += 1;
  const b = buscas[i] && buscas[i].json ? buscas[i].json : { nicho: '?', q: '?' };
  if (!porNicho[b.nicho]) porNicho[b.nicho] = { chamadas: 0, palavras: [], ids: {} };
  const grupo = porNicho[b.nicho];
  grupo.chamadas += 1;
  if (grupo.palavras.indexOf(b.q) < 0) grupo.palavras.push(b.q);
  const r = it.json || {};
  const corpo = r.body && typeof r.body === 'object' ? r.body : r;
  const status = Number(r.statusCode || 200);
  if (status >= 400 || corpo.error) {
    const e = corpo.error || {};
    const bruto = JSON.stringify(e);
    const razao = e.errors && e.errors[0] ? String(e.errors[0].reason || '') : '';
    if (razao === 'quotaExceeded' || razao === 'dailyLimitExceeded' || razao === 'rateLimitExceeded') quotaExcedida = true;
    if (status === 403 && (bruto.indexOf('SCOPE_INSUFFICIENT') >= 0 || bruto.indexOf('insufficientPermissions') >= 0 || bruto.indexOf('insufficient authentication scopes') >= 0)) erroEscopo = true;
    erros.push('search [' + b.nicho + '] "' + b.q + '": HTTP ' + status + ' ' + razao + ' ' + String(e.message || '').slice(0, 140));
    return;
  }
  (corpo.items || []).forEach(function (v) {
    const id = v.id && v.id.videoId;
    if (!id) return;
    if (!grupo.ids[id]) grupo.ids[id] = [];
    if (grupo.ids[id].indexOf(b.q) < 0) grupo.ids[id].push(b.q);
  });
});
const unicos = {};
let duplicados = 0;
Object.keys(porNicho).forEach(function (n) {
  Object.keys(porNicho[n].ids).forEach(function (id) {
    unicos[id] = true;
    if (porNicho[n].ids[id].length > 1) duplicados += 1;
  });
});
const ids = Object.keys(unicos);
const meta = { erros: erros, chamadas_search: chamadas, quota_excedida: quotaExcedida, erro_escopo: erroEscopo, total_ids_unicos: ids.length, duplicados: duplicados, por_nicho: porNicho };
const lotes = [];
for (let i = 0; i < ids.length; i += 50) lotes.push(ids.slice(i, i + 50));
if (!lotes.length) lotes.push(['nenhum']); // videos.list com id inexistente devolve lista vazia (1 unidade) e mantém o fluxo vivo
return lotes.map(function (l, k) {
  const j = { ids: l.join(','), lote: k + 1, vazio: ids.length === 0 };
  if (k === 0) j.meta = meta;
  return { json: j };
});

// Radar do YouTube (multi-nicho) - nó "Consolidar videos": lê o videos.list, trata vídeo sem estatísticas, converte a duração ISO 8601 e aplica o filtro de duração.
// Guarda o idioma declarado e um palpite pelo título (o filtro de idioma é aplicado por nicho no nó seguinte). Monta lotes de até 50 canais para o channels.list.
const cfg = $('Montar buscas').first().json.cfg;
const videos = {};
const erros = [];
let detalhados = 0;
let semEstatisticas = 0;
let longos = 0;
const MARCAS_PT = [' você ', ' voce ', ' não ', ' nao ', ' uma ', ' seu ', ' sua ', ' com ', ' para ', ' pra ', ' quando ', ' amor ', ' dele ', ' dela ', ' como ', ' mais ', ' isso ', ' ele ', ' ela ', ' ção', 'ções', 'ão ', 'ões '];
const MARCAS_OUTRO = [' the ', ' you ', ' your ', ' and ', ' of ', ' he ', ' she ', ' his ', ' her ', ' how ', ' why ', ' with ', ' when ', ' el ', ' los ', ' las ', ' una ', ' tu ', ' es ', ' pero ', ' le ', ' est ', ' pas ', ' und ', ' der ', ' nicht '];
const achaPt = function (titulo) {
  const t = ' ' + String(titulo || '').toLowerCase().replace(/[#!?.,:;()|"]/g, ' ').replace(/ +/g, ' ') + ' ';
  let a = 0;
  let b = 0;
  MARCAS_PT.forEach(function (m) { if (t.indexOf(m) >= 0) a += 1; });
  MARCAS_OUTRO.forEach(function (m) { if (t.indexOf(m) >= 0) b += 1; });
  return a > b;
};
const duracaoSeg = function (d) {
  const m = /^P(?:([0-9]+)D)?T?(?:([0-9]+)H)?(?:([0-9]+)M)?(?:([0-9]+)S)?$/.exec(String(d || ''));
  if (!m) return null;
  return Number(m[1] || 0) * 86400 + Number(m[2] || 0) * 3600 + Number(m[3] || 0) * 60 + Number(m[4] || 0);
};
$input.all().forEach(function (it, i) {
  const r = it.json || {};
  const corpo = r.body && typeof r.body === 'object' ? r.body : r;
  const status = Number(r.statusCode || 200);
  if (status >= 400 || corpo.error) {
    const e = corpo.error || {};
    const razao = e.errors && e.errors[0] ? String(e.errors[0].reason || '') : '';
    erros.push('videos.list lote ' + (i + 1) + ': HTTP ' + status + ' ' + razao + ' ' + String(e.message || '').slice(0, 140));
    return;
  }
  (corpo.items || []).forEach(function (v) {
    detalhados += 1;
    const est = v.statistics || {};
    if (est.viewCount === undefined) {
      semEstatisticas += 1;
      return;
    }
    const dur = duracaoSeg(v.contentDetails && v.contentDetails.duration);
    if (dur === null || dur > cfg.duracao_max_s) {
      longos += 1;
      return;
    }
    const s = v.snippet || {};
    videos[v.id] = {
      id: v.id,
      titulo: String(s.title || ''),
      canal_id: s.channelId,
      canal: String(s.channelTitle || ''),
      publicado: s.publishedAt,
      views: Number(est.viewCount),
      curtidas: est.likeCount === undefined ? null : Number(est.likeCount),
      comentarios: est.commentCount === undefined ? null : Number(est.commentCount),
      duracao_s: dur,
      declarado: String(s.defaultAudioLanguage || s.defaultLanguage || '').toLowerCase(),
      titulo_pt: achaPt(s.title) || achaPt(s.channelTitle),
    };
  });
});
const canais = [];
Object.keys(videos).forEach(function (id) {
  if (canais.indexOf(videos[id].canal_id) < 0) canais.push(videos[id].canal_id);
});
const lotes = [];
for (let i = 0; i < canais.length; i += 50) lotes.push(canais.slice(i, i + 50));
if (!lotes.length) lotes.push(['nenhum']);
return lotes.map(function (l, k) {
  const j = { ids: l.join(','), lote: k + 1 };
  if (k === 0) j.dados = { videos: videos, erros: erros, detalhados: detalhados, sem_estatisticas: semEstatisticas, acima_da_duracao: longos, lotes_videos: $input.all().length };
  return { json: j };
});

// Radar do YouTube (multi-nicho) - nó "Pontuar e filtrar": para CADA nicho junta canais e vídeos, aplica idioma, inscritos e views, calcula outlier, velocidade, engajamento,
// padrão do título e idade do canal, e monta a linha do ranking do nicho. Devolve UM item com as linhas, o ranking, o resumo e a linha da aba execucoes.
const base = $('Montar buscas').first().json;
const cfg = base.cfg;
const meta = $('Consolidar buscas').first().json.meta;
const dados = $('Consolidar videos').first().json.dados;
const videos = dados.videos;
const erros = [].concat(meta.erros, dados.erros, base.avisos || []);
const idiomaDoNicho = {};
$('Montar buscas').all().forEach(function (i) { idiomaDoNicho[i.json.nicho] = i.json.relevanceLanguage; });
const canais = {};
$input.all().forEach(function (it, i) {
  const r = it.json || {};
  const corpo = r.body && typeof r.body === 'object' ? r.body : r;
  const status = Number(r.statusCode || 200);
  if (status >= 400 || corpo.error) {
    const e = corpo.error || {};
    const razao = e.errors && e.errors[0] ? String(e.errors[0].reason || '') : '';
    erros.push('channels.list lote ' + (i + 1) + ': HTTP ' + status + ' ' + razao + ' ' + String(e.message || '').slice(0, 140));
    return;
  }
  (corpo.items || []).forEach(function (c) {
    const est = c.statistics || {};
    canais[c.id] = {
      titulo: String((c.snippet || {}).title || ''),
      criado: (c.snippet || {}).publishedAt,
      oculto: est.hiddenSubscriberCount === true || est.subscriberCount === undefined,
      inscritos: est.subscriberCount === undefined ? null : Number(est.subscriberCount),
    };
  });
});
const TERMOS = ['gaslighting', 'love bombing', 'narcisis', 'narcisismo', 'manipula', 'darvo', 'triangula', 'hoovering', 'flying monkey', 'abus', 'toxic', 'psicopata', 'sociopata', 'codependen', 'dissonancia', 'apego', 'creepypasta', 'serial killer', 'buraco negro', 'estoicismo', 'mitologia'];
const padraoTitulo = function (t) {
  const limpo = String(t || '').replace(/#[^ ]+/g, ' ').replace(/ +/g, ' ').trim();
  if (/^(top )?[0-9]+/i.test(limpo)) return 'numero_no_inicio';
  if (/["“”«»]/.test(limpo)) return 'aspas';
  if (limpo.indexOf('?') >= 0) return 'pergunta';
  const baixo = limpo.toLowerCase();
  const palavras = limpo.split(' ').filter(Boolean).length;
  if (palavras <= 4 && TERMOS.some(function (x) { return baixo.indexOf(x) >= 0; })) return 'termo_tecnico_isolado';
  return 'outro';
};
const arred = function (n, d) { const f = Math.pow(10, d); return Math.round(n * f) / f; };
const mediana = function (a) {
  if (!a.length) return 0;
  const s = a.slice().sort(function (x, y) { return x - y; });
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
const agoraMs = Date.now();
const linhas = [];
const ranking = [];
const funil = [];
Object.keys(meta.por_nicho).forEach(function (nicho) {
  const g = meta.por_nicho[nicho];
  const lang = idiomaDoNicho[nicho] || 'pt';
  const f = { achados: Object.keys(g.ids).length, detalhados_ok: 0, outro_idioma: 0, sem_canal: 0, canal_oculto: 0, acima_de_inscritos: 0, abaixo_de_views: 0 };
  const doNicho = [];
  Object.keys(g.ids).forEach(function (id) {
    const v = videos[id];
    if (!v) return; // fora da duração, sem estatísticas ou erro no videos.list (contados em dados)
    f.detalhados_ok += 1;
    let idioma = v.declarado ? v.declarado : '?';
    if (cfg.filtrar_idioma) {
      if (v.declarado) {
        if (v.declarado.indexOf(lang) !== 0) { f.outro_idioma += 1; return; }
      } else if (lang === 'pt' && v.titulo_pt) {
        idioma = 'pt (titulo)';
      } else { f.outro_idioma += 1; return; }
    }
    const canal = canais[v.canal_id];
    if (!canal) { f.sem_canal += 1; return; }
    if (canal.oculto) { f.canal_oculto += 1; return; }
    if (canal.inscritos > cfg.inscritos_max) { f.acima_de_inscritos += 1; return; }
    if (v.views < cfg.views_min) { f.abaixo_de_views += 1; return; }
    const horas = Math.max(1, (agoraMs - Date.parse(v.publicado)) / 3600000);
    const idade = canal.criado ? (agoraMs - Date.parse(canal.criado)) / (30.4375 * 86400000) : null;
    const palavras = g.ids[id] || [];
    doNicho.push({
      chave: base.ciclo + '|' + nicho + '|' + id,
      ciclo: base.ciclo,
      nicho: nicho,
      data_execucao: base.agora_br,
      palavra_chave: palavras[0] || '',
      titulo: v.titulo,
      link: 'https://www.youtube.com/shorts/' + id,
      canal: canal.titulo || v.canal,
      link_canal: 'https://www.youtube.com/channel/' + v.canal_id,
      canal_id: v.canal_id,
      inscritos: canal.inscritos,
      views: v.views,
      curtidas: v.curtidas === null ? '' : v.curtidas,
      comentarios: v.comentarios === null ? '' : v.comentarios,
      duracao_s: v.duracao_s,
      publicado_em: v.publicado,
      outlier: arred(v.views / Math.max(canal.inscritos, 500), 2),
      velocidade_views_h: arred(v.views / horas, 1),
      engajamento: arred(((v.curtidas || 0) + (v.comentarios || 0)) / Math.max(v.views, 1), 4),
      padrao_titulo: padraoTitulo(v.titulo),
      canal_novo: idade !== null && idade < 6 ? 'sim' : 'nao',
      idade_canal_meses: idade === null ? '' : arred(idade, 1),
      palavras_que_acharam: palavras.join(' | '),
      idioma: idioma,
    });
  });
  doNicho.sort(function (a, b) { return b.outlier - a.outlier; });
  const porCanal = {};
  let totalViews = 0;
  doNicho.forEach(function (l) {
    porCanal[l.canal_id] = (porCanal[l.canal_id] || 0) + l.views;
    totalViews += l.views;
  });
  const idsCanais = Object.keys(porCanal);
  const maior = idsCanais.reduce(function (m, k) { return Math.max(m, porCanal[k]); }, 0);
  const conc = totalViews > 0 ? maior / totalViews : 0;
  const med = mediana(doNicho.map(function (l) { return l.outlier; }));
  ranking.push({
    chave: base.ciclo + '|' + nicho,
    ciclo: base.ciclo,
    data_execucao: base.agora_br,
    nicho: nicho,
    palavras_usadas: g.palavras.join('; '),
    chamadas_search: g.chamadas,
    videos_achados: f.achados,
    videos_outlier: doNicho.length,
    canais_pequenos: idsCanais.length,
    mediana_outlier: arred(med, 2),
    concentracao_top_canal: arred(conc, 3),
    duracao_mediana_s: arred(mediana(doNicho.map(function (l) { return l.duracao_s; })), 1),
    score: arred(idsCanais.length * med * (1 - conc), 2),
    outlier_maximo: doNicho.length ? doNicho[0].outlier : 0,
  });
  funil.push(Object.assign({ nicho: nicho, saida: doNicho.length }, f));
  doNicho.forEach(function (l) { linhas.push(l); });
});
ranking.sort(function (a, b) { return b.score - a.score; });
const unidades = meta.chamadas_search * 100 + dados.lotes_videos + $input.all().length;
if (meta.erro_escopo) erros.push('ESCOPO: a credencial OAuth do YouTube não tem permissão para search.list/videos.list; é preciso uma chave de API do YouTube Data API v3 (ver a seção Autenticação do README)');
if (meta.quota_excedida) erros.push('COTA: a API respondeu quotaExceeded; o relatório pode estar incompleto');
const nichosFeitos = ranking.map(function (r) { return r.nicho; });
const obs = funil.map(function (x) { return x.nicho + ': ' + x.achados + ' achados > ' + x.detalhados_ok + ' ok > idioma -' + x.outro_idioma + ' > inscritos -' + x.acima_de_inscritos + ' > views -' + x.abaixo_de_views + ' = ' + x.saida; }).join(' | ') + ' || fora da duração ' + dados.acima_da_duracao + '; sem estatísticas ' + dados.sem_estatisticas + '; duplicados no nicho ' + meta.duplicados + '; ids únicos ' + meta.total_ids_unicos + '; restam para amanhã ' + base.nichos_restantes_para_amanha + ' nicho(s)';
const resumo = { chamadas_search: meta.chamadas_search, unidades_cota: unidades, ids_unicos: meta.total_ids_unicos, duplicados_no_nicho: meta.duplicados, videos_detalhados: dados.detalhados, sem_estatisticas: dados.sem_estatisticas, acima_da_duracao: dados.acima_da_duracao, funil: funil, restam_para_amanha: base.nichos_restantes_para_amanha };
return [{
  json: {
    linhas: linhas,
    ranking: ranking,
    resumo: resumo,
    erros: erros,
    cfg: cfg,
    modo: base.modo,
    hoje: base.hoje,
    agora_br: base.agora_br,
    ciclo: base.ciclo,
    enviar_email: base.modo === 'teste' ? true : base.completo_apos === true,
    execucao: {
      data_execucao: base.agora_br,
      modo: base.modo,
      palavras_usadas: nichosFeitos.join('; '),
      chamadas_search_list: meta.chamadas_search,
      unidades_cota_estimadas: unidades,
      videos_encontrados: meta.total_ids_unicos,
      videos_apos_filtros: linhas.length,
      linhas_gravadas: linhas.length,
      erros: erros.join(' || ').slice(0, 900),
      observacoes: obs.slice(0, 1800),
    },
  },
}];

// Radar do YouTube (multi-nicho) - nó "Execucao abortada": monta a linha da aba execucoes quando não há o que fazer hoje
// (ciclo já completo, nenhum nicho ativo ou cota do dia sem espaço para o próximo nicho).
const d = $input.first().json;
return [{
  json: {
    execucao: {
      data_execucao: d.agora_br,
      modo: d.modo,
      palavras_usadas: '',
      chamadas_search_list: 0,
      unidades_cota_estimadas: 0,
      videos_encontrados: 0,
      videos_apos_filtros: 0,
      linhas_gravadas: 0,
      erros: '',
      observacoes: 'SEM BUSCA: ' + d.motivo + ' | ciclo ' + d.ciclo + '; limite ' + d.limite_search_dia + ' chamadas/dia; já usadas hoje ' + d.chamadas_ja_usadas_hoje + '; nichos ativos ' + d.nichos_ativos,
    },
  },
}];

// Radar do YouTube (multi-nicho) - nó "Montar e-mail": ranking dos nichos (aba ranking_nichos do ciclo) + top N outliers de cada nicho + cota e funil.
// Teste manual: usa só os dados desta execução. Semanal: usa o que está na planilha para o ciclo (que junta os dias em que o ciclo foi sendo completado).
const p = $('Pontuar e filtrar').first().json;
const esc = function (s) {
  return String(s === undefined || s === null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
};
const n = function (v) { return Number(v).toLocaleString('pt-BR'); };
const d1 = function (v) { return (Math.round(Number(v) * 100) / 100).toLocaleString('pt-BR'); };
let ranking = p.ranking;
let linhas = p.linhas;
if (p.modo !== 'teste') {
  ranking = $('Ler ranking do ciclo').all().map(function (i) { return i.json; }).filter(function (r) { return String(r.ciclo || '') === p.ciclo && r.nicho; });
  linhas = $('Ler resultados do ciclo').all().map(function (i) { return i.json; }).filter(function (r) { return String(r.ciclo || '') === p.ciclo && r.nicho; });
  ranking.forEach(function (r) { r.score = Number(r.score); });
  linhas.forEach(function (l) { l.outlier = Number(l.outlier); });
}
ranking = ranking.slice().sort(function (a, b) { return Number(b.score) - Number(a.score); });
const partes = [];
partes.push('<div style="font-family:Arial,Helvetica,sans-serif;color:#222;max-width:960px">');
partes.push('<h2 style="margin:0 0 6px">Radar multi-nicho</h2>');
partes.push('<p style="margin:0 0 12px;color:#555">' + esc(p.agora_br) + ' (Brasília) · ciclo ' + esc(p.ciclo) + ' · modo ' + esc(p.modo) + ' · ' + ranking.length + ' nicho(s) no ranking</p>');
if (p.erros.length) {
  partes.push('<p style="background:#fdecea;border-left:4px solid #c0392b;padding:8px 12px"><b>Avisos e erros:</b><br>' + p.erros.map(esc).join('<br>') + '</p>');
}
partes.push('<h3 style="margin:12px 0 4px">Ranking dos nichos</h3>');
partes.push('<p style="margin:0 0 6px;color:#666;font-size:12px">Pontuação = canais pequenos distintos × mediana do outlier × (1 − parcela de views do maior canal). Sobe quando há muitos canais pequenos se saindo bem, sem depender de um só.</p>');
partes.push('<table style="border-collapse:collapse;width:100%;font-size:13px">');
partes.push('<tr style="background:#2b1d24;color:#fff;text-align:left"><th style="padding:6px">#</th><th style="padding:6px">Nicho</th><th style="padding:6px;text-align:right">Vídeos outlier</th><th style="padding:6px;text-align:right">Canais pequenos</th><th style="padding:6px;text-align:right">Mediana outlier</th><th style="padding:6px;text-align:right">Maior canal (views)</th><th style="padding:6px;text-align:right">Duração mediana</th><th style="padding:6px;text-align:right">Pontuação</th></tr>');
ranking.forEach(function (r, i) {
  const fundo = i % 2 ? '#f6f1f3' : '#ffffff';
  partes.push('<tr style="background:' + fundo + '"><td style="padding:6px">' + (i + 1) + '</td><td style="padding:6px"><b>' + esc(r.nicho) + '</b></td><td style="padding:6px;text-align:right">' + n(r.videos_outlier) + '</td><td style="padding:6px;text-align:right">' + n(r.canais_pequenos) + '</td><td style="padding:6px;text-align:right">' + d1(r.mediana_outlier) + '×</td><td style="padding:6px;text-align:right">' + Math.round(Number(r.concentracao_top_canal) * 100) + '%</td><td style="padding:6px;text-align:right">' + d1(r.duracao_mediana_s) + ' s</td><td style="padding:6px;text-align:right"><b>' + d1(r.score) + '</b></td></tr>');
});
partes.push('</table>');
ranking.forEach(function (r) {
  const top = linhas.filter(function (l) { return l.nicho === r.nicho; }).sort(function (a, b) { return Number(b.outlier) - Number(a.outlier); }).slice(0, p.cfg.top_por_nicho);
  partes.push('<h3 style="margin:18px 0 4px">' + esc(r.nicho) + '</h3>');
  if (!top.length) {
    partes.push('<p style="margin:0;color:#777">Nenhum vídeo passou nos filtros neste nicho (duração ≤ ' + p.cfg.duracao_max_s + ' s, canal ≤ ' + n(p.cfg.inscritos_max) + ' inscritos, ≥ ' + n(p.cfg.views_min) + ' views, últimos ' + p.cfg.janela_dias + ' dias).</p>');
    return;
  }
  partes.push('<table style="border-collapse:collapse;width:100%;font-size:13px">');
  top.forEach(function (l, i) {
    const fundo = i % 2 ? '#f6f1f3' : '#ffffff';
    partes.push('<tr style="background:' + fundo + '"><td style="padding:5px">' + (i + 1) + '</td><td style="padding:5px"><a href="' + esc(l.link) + '">' + esc(l.titulo) + '</a>' + (l.canal_novo === 'sim' ? ' <span style="color:#b5651d">(canal novo)</span>' : '') + '</td><td style="padding:5px"><a href="' + esc(l.link_canal) + '">' + esc(l.canal) + '</a></td><td style="padding:5px;text-align:right">' + n(l.inscritos) + ' insc.</td><td style="padding:5px;text-align:right">' + n(l.views) + ' views</td><td style="padding:5px;text-align:right"><b>' + d1(l.outlier) + '×</b></td><td style="padding:5px">' + esc(l.padrao_titulo) + '</td></tr>');
  });
  partes.push('</table>');
});
const r = p.resumo;
partes.push('<h3 style="margin:18px 0 4px">Cota desta execução</h3>');
partes.push('<p style="margin:0;color:#444">search.list: ' + r.chamadas_search + ' chamada(s) (' + (r.chamadas_search * 100) + ' unidades) · total estimado: ' + n(r.unidades_cota) + ' de 10.000 unidades/dia (compartilhadas com qualquer outro uso do mesmo projeto do Google) · ids únicos ' + r.ids_unicos + ' · fora da duração ' + r.acima_da_duracao + ' · restam para os próximos dias: ' + r.restam_para_amanha + ' nicho(s)</p>');
partes.push('<p style="color:#888;font-size:12px;margin-top:16px">Sinal de tema e padrão, não de cópia: o conteúdo do canal continua original. Planilha do radar: abas resultados e ranking_nichos.</p>');
partes.push('</div>');
const assunto = (p.modo === 'teste' ? '[TESTE] ' : '') + 'Radar multi-nicho: ' + ranking.length + ' nichos (ciclo ' + p.ciclo + ')';
return [{ json: { para: p.cfg.email_destino, assunto: assunto, html: partes.join('') } }];
